#!/usr/bin/env node
import { readFileSync, symlinkSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';

const args = process.argv.slice(2);
const value = (flag) => {
  const index = args.indexOf(flag);
  return index >= 0 ? args[index + 1] : null;
};
const workspace = value('--workspace');
const promptPath = value('--prompt-file');
const prompt = promptPath ? readFileSync(promptPath, 'utf8') : '';
const requested = process.env.FAKE_MUSE_MODE ?? 'auto';
let mode =
  requested === 'auto'
    ? (prompt.includes('current approved application') && prompt.includes('index.html')
        ? 'modify'
        : 'generate')
    : requested;
const emit = (event) => process.stdout.write(`${JSON.stringify(event)}\n`);
const usage = (calls, input = 100, output = 10) =>
  emit({
    payload_type: 'run.usage',
    payload: { calls, models: [{ input_tokens: input, output_tokens: output }] },
  });
const done = (text) =>
  emit({ payload_type: 'run.terminal', payload: { terminal: 'completed', text } });

function html(marker) {
  return `<!doctype html><html><head><title>Fake Game</title></head><body>
<div id="game"></div>
<script src="https://cdn.jsdelivr.net/npm/phaser@3.80.1/dist/phaser.min.js"></script>
<script>
const FARM_MARKER = 'keep-me';
const MARKER = '${marker}';
new Phaser.Game({
  type: Phaser.AUTO, width: 640, height: 480, parent: 'game', backgroundColor: '#ffe08a',
  scene: { create() {
    const g = this.add.graphics();
    g.fillStyle(0xff5d5d, 1); g.fillRect(40, 40, 220, 140);
    g.fillStyle(0x4da3ff, 1); g.fillCircle(480, 140, 70);
    g.fillStyle(0x4caf50, 1); g.fillRect(40, 300, 560, 80);
    this.add.text(60, 230, 'Fake Farm Game', { fontSize: '36px', color: '#333333' });
  } }
});
</script>
</body></html>`;
}

const usesApiKey = args.includes('--api-key-stdin');
if (mode === 'quota-once' && !usesApiKey) {
  process.stderr.write(
    'run ended with Failed: API error 429: Subscription quota exhausted. (rate_limit_error)\n',
  );
  process.exit(1);
}

if (!workspace) {
  process.stderr.write('missing --workspace\n');
  process.exit(2);
}

const quota = () => {
  process.stderr.write(
    'run ended with Failed: API error 429: Subscription quota exhausted. (rate_limit_error)\n',
  );
  process.exit(1);
};

if (mode === 'leak') {
  process.stderr.write(
    `Authorization: Bearer abcdefghijklmnop1234567890\napi_key=supersecretvalue\nsecret=${process.env.FAKE_SECRET ?? 'none'}\n`,
  );
  process.exit(1);
}
if (mode === 'auth-fail') {
  process.stderr.write('run ended with Failed: API error 401 unauthorized (credential_rejected)\n');
  process.exit(1);
}
if (mode === 'network-fail') {
  process.stderr.write('connect ECONNRESET 127.0.0.1:443\n');
  process.exit(1);
}
if (mode === 'always-quota') quota();
if (mode === 'quota-corrupt' && !usesApiKey) {
  writeFileSync(join(workspace, 'index.html'), '<html><body>corrupted by primary</body></html>');
  quota();
}
if (mode === 'quota-corrupt') {
  mode = prompt.includes('current approved application') ? 'modify' : 'generate';
}
if (mode === 'quota-then-invalid' && !usesApiKey) quota();
if (mode === 'quota-then-invalid') {
  writeFileSync(join(workspace, 'index.html'), '<!doctype html><html><body></body></html>');
  usage(2);
  done('invalid fallback');
  process.exit(0);
} else if (mode === 'quota-usage' && !usesApiKey) {
  usage(3);
  quota();
}

if (mode === 'sleep') {
  setTimeout(() => {
    usage(1);
    done('slow');
  }, 30_000);
} else if (mode === 'copy') {
  // Deterministic transport for recorded/authentic sources. The file is chosen
  // by the test or evaluation harness, never generated by the CLI: this mode
  // exists so Forge's real validation/approval pipeline can be exercised on
  // known bytes without a live model call.
  const source = process.env.FAKE_MUSE_HTML;
  if (!source) {
    process.stderr.write('FAKE_MUSE_HTML is not set\n');
    process.exit(4);
  }
  writeFileSync(join(workspace, 'index.html'), readFileSync(source, 'utf8'));
  usage(2);
  done('copied');
} else if (mode === 'app') {
  // Deterministic non-game application for the Studio browser verification.
  // No network asset, so approval's real Chrome runtime check can run offline.
  const file = join(workspace, 'index.html');
  const source = process.env.FAKE_MUSE_APP ?? 'tests/fixtures/general-app-form.html';
  if (prompt.includes('current approved application')) {
    const existing = readFileSync(file, 'utf8');
    const updated = existing.replace(
      '</body>',
      '<button id="verification-change" type="button">Verification change</button>\n' +
        "<script>document.getElementById('verification-change').addEventListener('click',function(){this.textContent='Verification change applied';});</script>\n" +
        '</body>',
    );
    if (updated === existing) {
      process.stderr.write('expected an existing document to modify\n');
      process.exit(3);
    }
    writeFileSync(file, updated);
    usage(2);
    done('app modified');
  } else {
    writeFileSync(file, readFileSync(source, 'utf8'));
    usage(2);
    done('app generated');
  }
} else if (mode === 'fail') {
  process.stderr.write('fake failure\n');
  process.exit(1);
} else if (mode === 'symlink') {
  symlinkSync('/etc/passwd', join(workspace, 'index.html'));
  usage(1);
  done('symlinked');
} else if (mode === 'invalid') {
  writeFileSync(join(workspace, 'index.html'), '<!doctype html><html><body></body></html>');
  usage(1);
  done('invalid');
} else if (mode === 'budget') {
  writeFileSync(join(workspace, 'index.html'), html('budget'));
  usage(99, 5_000_000);
  done('budget');
} else if (mode === 'modify') {
  const file = join(workspace, 'index.html');
  const existing = readFileSync(file, 'utf8');
  if (!existing.includes('FARM_MARKER')) {
    process.stderr.write('expected the approved game to be seeded into staging\n');
    process.exit(3);
  }
  const updated = existing
    .replace('<title>Fake Game</title>', '<title>Fake Game v2</title>')
    .replace('</body>', '<script>const CHANGE_MARKER = \'v2\';</script></body>');
  writeFileSync(file, updated);
  usage(2);
  done('modified');
} else {
  writeFileSync(join(workspace, 'index.html'), html('v1'));
  usage(2);
  done('generated');
}
